{
  "root_cause": "The Tab keydown event on the datepicker input has defaultPrevented set to true, likely due to a vanilla-calendar-pro (VCP) keydown listener that calls preventDefault() on Tab key. This blocks the browser's default focus navigation to the next form field.",
  "repair_strategy": "Add a capture-phase keydown listener on the datepicker input that calls stopImmediatePropagation() on Tab key to prevent VCP's listener from running, then hides the calendar. This allows the browser's default focus move to proceed while closing the datepicker popup.",
  "edits": [
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "class Datepicker extends BaseComponent {
  protected declare _element: HTMLElement & { value: string }
  protected declare _config: DatepickerConfig
  protected declare _calendar: Calendar | null
  protected declare _isShown: boolean
  protected declare _isInput: boolean
  protected declare _isInline: boolean
  protected declare _boundInput: HTMLInputElement | null
  protected declare _positionElement: HTMLElement
  protected declare _displayElement: HTMLElement | false | null
  protected declare _themeObserver: MutationObserver | null
  protected declare _themeAncestor: Element | null | undefined
  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void",
      "after": "class Datepicker extends BaseComponent {
  protected declare _element: HTMLElement & { value: string }
  protected declare _config: DatepickerConfig
  protected declare _calendar: Calendar | null
  protected declare _isShown: boolean
