    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
    super(element, config)

    this._calendar = null
    this._isShown = false

    this._initCalendar()
  }",
      "after": "  constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
    super(element, config)

    this._calendar = null
    this._isShown = false
    this._onTabKeyDownCapture = null

    this._initCalendar()
  }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "    // Set initial value if input has a value
    if (this._isInput && this._element.value) {
      this._parseInputValue()
    }

    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()
  }",
      "after": "    // Set initial value if input has a value
    if (this._isInput && this._element.value) {
      this._parseInputValue()
    }

    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()

    // Set up Tab key capture listener to hide calendar without preventing default focus move
    if (this._isInput) {
      this._onTabKeyDownCapture = (event: KeyboardEvent) => {
        if (event.key === 'Tab') {
          event.stopImmediatePropagation()
          this.hide()
        }
      }
      this._element.addEventListener('keydown', this._onTabKeyDownCapture, { capture: true })
    }
  }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  override dispose(): void {
    if (this._themeObserver) {
      this._themeObserver.disconnect()
      this._themeObserver = null
    }

    if (this._onOutside) {
      EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
      EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
    }

    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }",
      "after": "  override dispose(): void {
    if (this._themeObserver) {
      this._themeObserver.disconnect()
      this._themeObserver = null
    }

    if (this._onOutside) {
      EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
      EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
    }

    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    // Clean up Tab key capture listener
    if (this._onTabKeyDownCapture) {
      this._element.removeEventListener('keydown', this._onTabKeyDownCapture, { capture: true })
      this._onTabKeyDownCapture = null
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }"
    }
  ],
  "expected_accessibility_effect": "Tab key navigation from the departure date field moves focus to the passengers field as expected. The datepicker popup closes when tabbing out, maintaining a predictable keyboard interface.",
  "functional_risks": [
    "Capture-phase listener might interfere with other capture-phase listeners (unlikely in this codebase).",
    "stopImmediatePropagation prevents all other keydown listeners on the input for Tab key, but the calendar doesn't use Tab internally.",
    "Direct addEventListener usage bypasses EventHandler, but is necessary for capture phase."
  ],
  "verification_requirements": [
    "Verify Tab from departure date moves focus to passengers field.",
    "Verify datepicker calendar closes when tabbing out.",
    "Verify Tab works when datepicker not open.",
    "Verify Shift+Tab reverse tabbing works.",
    "Verify date selection via mouse/keyboard in calendar works."
  ]
}
